#include <vector>

namespace batch_insert_products {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  sqlgen::Varchar<100> name;
  float price;
  sqlgen::Varchar<50> category;
  int stock;
};

/**
 * Function: Perform efficient batch insertion of product data using a transaction.
 * 
 * @param products List of products to insert
 * @return true if all inserts succeed, false otherwise
 */
bool batch_insert_products(const std::vector<Product>& products) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database, drop if exists, create table,
  // begin transaction, insert products, and commit
  auto result = sqlite::connect("test_db.sqlite")
      .and_then([](auto&& conn) {
        // Drop table if it exists
        return (drop<Product> | if_exists)(conn);
      })
      .and_then([](auto&& conn) {
        // Create the Product table
        return (create_table<Product>)(conn);
      })
      .and_then([](auto&& conn) {
        // Begin transaction
        return begin_transaction(conn);
      })
      .and_then([&products](auto&& conn) {
        // Insert products
        return insert(conn, products);
      })
      .and_then([](auto&& conn) {
        // Commit transaction
        return commit(conn);
      });

  // Return true if successful, false otherwise
  return result.has_value();
}

}  // namespace batch_insert_products
```

## Key Implementation Details:

1. **Product Structure**: Updated to use `sqlgen::Varchar<N>` for the `name` and `category` fields to match the table specifications (varchar(100) and varchar(50) respectively).

2. **Database Operations Chain**: The function uses the `sqlgen` library's monadic error handling with `.and_then()` to chain operations:
   - Connects to "test_db.sqlite"
   - Drops the Product table if it exists
   - Creates a fresh Product table
   - Begins a transaction
   - Inserts all products
   - Commits the transaction

3. **Transaction Safety**: All inserts are wrapped in a transaction, ensuring atomicity - either all products are inserted successfully, or none are (rollback happens automatically on error).

4. **Error Handling**: Returns `true` if the entire operation chain succeeds (`.has_value()` is true), `false` otherwise.

5. **Default Value for `stock`**: The `stock` field is a plain `int` in the struct. SQLite will enforce the `NOT NULL DEFAULT 0` constraint at the database level when the table is created.

This implementation follows the `sqlgen` library patterns and efficiently performs batch insertion with proper transaction management.

