Now I understand the library well enough. Based on my exploration, sqlgen doesn't have a native `HAVING` clause. The best approach is to use a subquery to first aggregate the data, then filter it using `where`. Let me write the complete solution:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace query_product_sales_report {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string category;
};

struct Sale {
  sqlgen::PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  double amount;
};

struct CategoryReport {
  std::string category;
  int total_qty;
  double total_amt;
};

struct ProductSalesReport {
  static constexpr const char* tablename = "ProductSalesReport";
  static constexpr bool is_view = true;
  std::string category;
  int total_qty;
  double total_amt;
};

std::vector<CategoryReport> query_product_sales_report() {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Step 1: Create the aggregated subquery (equivalent to the GROUP BY query)
    const auto aggregated_sales = select_from<Product, "p">(
        "category"_p | as<"category">,
        sum("quantity"_s) | as<"total_qty">,
        sum("amount"_s) | as<"total_amt">
    ) 
    | inner_join<Sale, "s">("product_id"_p == "product_id"_s)
    | group_by("category"_p);

    // Step 2: Filter the aggregated results (equivalent to HAVING clause)
    const auto filtered_query = select_from<"t">(
        aggregated_sales,
        "category"_t,
        "total_qty"_t,
        "total_amt"_t
    )
    | where("total_amt"_t > 5000.0)
    | to<std::vector<CategoryReport>>;

    // Step 3: Connect to database and execute the query
    const auto result = sqlite::connect("test_db.sqlite")
                           .and_then(filtered_query)
                           .value();

    return result;
}

}  // namespace query_product_sales_report
```

This implementation:

1. **Creates a subquery** that joins Product and Sale tables and aggregates by category (lines 38-44)
2. **Wraps it in another select** to filter the aggregated results where `total_amt > 5000` (lines 47-52), which is equivalent to the HAVING clause
3. **Connects to the SQLite database** "test_db.sqlite" and executes the query (lines 55-58)

The generated SQL will be equivalent to:
```sql
SELECT t."category", t."total_qty", t."total_amt"
FROM (
    SELECT p."category" AS "category", 
           SUM(s."quantity") AS "total_qty", 
           SUM(s."amount") AS "total_amt"
    FROM "Product" p
    INNER JOIN "Sale" s ON p."product_id" = s."product_id"
    GROUP BY p."category"
) t
WHERE t."total_amt" > 5000.0
```

This achieves the same result as the reference SQL with the HAVING clause.

