```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace transaction_transfer_funds {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
};

bool transfer_funds(int from_account_id, int to_account_id, double amount) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite");
  if (!conn) {
    return false;
  }

  // Read the sender's account to check balance
  auto from_account_query = read<Account> | where("account_id"_c == from_account_id);
  auto from_account_result = from_account_query(conn);

  if (!from_account_result) {
    return false;
  }

  auto from_account = from_account_result.value();

  // Check if sender has sufficient funds
  if (from_account.balance < amount) {
    return false;
  }

  // Start transaction and perform the transfer
  auto deduct_from_sender = update<Account>("balance"_c.set("balance"_c - amount)) | 
                            where("account_id"_c == from_account_id);

  auto add_to_receiver = update<Account>("balance"_c.set("balance"_c + amount)) | 
                         where("account_id"_c == to_account_id);

  // Execute the transaction
  auto result = begin_transaction(conn)
                .and_then(deduct_from_sender)
                .and_then(add_to_receiver)
                .and_then(commit);

  return result.has_value();
}

}  // namespace transaction_transfer_funds
```

This implementation:

1. **Connects to the database**: Uses `sqlite::connect("test_db.sqlite")` to connect to the specified SQLite database file
2. **Checks sufficient funds**: Reads the sender's account first to verify they have enough balance before attempting the transfer
3. **Performs the transfer in a transaction**:
   - Starts a transaction with `begin_transaction`
   - Deducts the amount from the sender's balance
   - Adds the amount to the receiver's balance
   - Commits the transaction if all operations succeed
4. **Auto-rollback on failure**: If any step fails (including the balance check), the transaction will automatically rollback due to RAII
5. **Returns success/failure**: Returns `true` if the transfer was successful, `false` otherwise

The function uses sqlgen's monadic error handling with `.and_then()` to chain operations together, ensuring that if any step fails, the entire transaction is rolled back automatically.

