std::vector<OrderMetrics> calculate_order_metrics_impl(const std::vector<OrderItem>& items) {
  // Connect to SQLite database
  auto db = sqlgen::sqlite::Database("test_db.sqlite");

  // Create/ensure OrderItem table exists
  auto order_item_table = db.table<OrderItem>("OrderItem");
  order_item_table.create_if_not_exists();

  // Insert items into the table
  for (const auto& item : items) {
    order_item_table.insert(item);
  }

  // Build query with arithmetic operations using sqlgen's expression builder
  using namespace sqlgen;

  auto query = order_item_table
    .select()
    .columns(
      col(&OrderItem::item_id),
      col(&OrderItem::order_id),
      col(&OrderItem::product_id),
      col(&OrderItem::unit_price),
      col(&OrderItem::quantity),
      coalesce(col(&OrderItem::discount_rate), 0.0).as("discount_rate"),
      coalesce(col(&OrderItem::tax_rate), 0.0).as("tax_rate"),
      // Multiplication: unit_price * quantity
      (col(&OrderItem::unit_price) * col(&OrderItem::quantity)).as("gross_total"),
      // Discount calculation: gross_total * (1 - discount_rate/100)
      (col(&OrderItem::unit_price) * col(&OrderItem::quantity) * 
       (1.0 - coalesce(col(&OrderItem::discount_rate), 0.0) / 100.0)).as("discounted_total"),
      // Final total with tax: discounted_total * (1 + tax_rate/100)
      (col(&OrderItem::unit_price) * col(&OrderItem::quantity) * 
       (1.0 - coalesce(col(&OrderItem::discount_rate), 0.0) / 100.0) *
       (1.0 + coalesce(col(&OrderItem::tax_rate), 0.0) / 100.0)).as("final_total"),
      // Division: unit_price * quantity / quantity (simplifies to unit_price)
      (col(&OrderItem::unit_price) * col(&OrderItem::quantity) / 
       col(&OrderItem::quantity)).as("unit_cost"),
      // Modulo operation: quantity % 10
      (col(&OrderItem::quantity) % 10).as("quantity_group"),
      // Estimated profit: unit_price * 0.3
      (col(&OrderItem::unit_price) * 0.3).as("estimated_profit")
    );

  // Execute query and collect results
  std::vector<OrderMetrics> metrics;

  for (auto row : query.exec()) {
    OrderMetrics metric;
    row.get(0, metric.item_id);
    row.get(1, metric.order_id);
    row.get(2, metric.product_id);
    row.get(3, metric.unit_price);
    row.get(4, metric.quantity);
    row.get(5, metric.discount_rate);
    row.get(6, metric.tax_rate);
    row.get(7, metric.gross_total);
    row.get(8, metric.discounted_total);
    row.get(9, metric.final_total);
    row.get(10, metric.unit_cost);
    row.get(11, metric.quantity_group);
    row.get(12, metric.estimated_profit);

    metrics.push_back(metric);
  }

  return metrics;
}

