      // Division: unit_price * quantity / quantity (simplifies to unit_price)
      (col(&OrderItem::unit_price) * col(&OrderItem::quantity) / 
       col(&OrderItem::quantity)).as("unit_cost"),
      // Modulo operation: quantity % 10
      (col(&OrderItem::quantity) % 10).as("quantity_group"),
      // Estimated profit: unit_price * 0.3
      (col(&OrderItem::unit_price) * 0.3).as("estimated_profit")
    );

  // Execute query and collect results
  std::vector<OrderMetrics> metrics;

  for (auto row : query.exec()) {
    OrderMetrics metric;
    row.get(0, metric.item_id);
    row.get(1, metric.order_id);
    row.get(2, metric.product_id);
    row.get(3, metric.unit_price);
    row.get(4, metric.quantity);
    row.get(5, metric.discount_rate);
    row.get(6, metric.tax_rate);
    row.get(7, metric.gross_total);
    row.get(8, metric.discounted_total);
    row.get(9, metric.final_total);
    row.get(10, metric.unit_cost);
    row.get(11, metric.quantity_group);
    row.get(12, metric.estimated_profit);

    metrics.push_back(metric);
  }

  return metrics;
}

}  // namespace calculate_order_metrics
```

This implementation:

1. **Connects to SQLite database** (`test_db.sqlite`)
2. **Creates/uses the OrderItem table** based on the struct definition
3. **Inserts the provided items** into the table
4. **Performs arithmetic operations**:
   - **Multiplication**: `unit_price * quantity` for gross total
   - **Subtraction**: `1 - discount_rate/100` for discount calculation
   - **Division**: Discount and tax rate calculations, unit cost
   - **Modulo**: `quantity % 10` for quantity grouping
   - **Addition**: `1 + tax_rate/100` for tax application
5. **Handles NULL values** using `COALESCE` for optional discount/tax rates
6. **Maps results** to the `OrderMetrics` structure
7. **Returns comprehensive analysis** of all order items with calculated business metrics

The function demonstrates all required arithmetic operations while calculating realistic business metrics like gross totals, discounts, taxes, and profit margins.

