/**
 * description: join_orders_customers_payments.
 * This function demonstrates how to join three tables (Orders, Customers, and Payments)
 * and return a consolidated view with order_id, customer_name, and amount.
 * It orders the results by amount in descending order.
 * Returns: std::vector<Consolidated>.
 */
std::vector<Consolidated> join_orders_customers_payments() {
  // Connect to the SQLite database
  auto db = sqlgen::sqlite::Database("test_db.sqlite");

  // Define table references
  auto customers = sqlgen::Table<Customer>(db, "Customer");
  auto orders = sqlgen::Table<Order>(db, "Order");
  auto payments = sqlgen::Table<Payment>(db, "Payment");

  // Build and execute the query with inner joins
  auto results = sqlgen::Query<Consolidated>(db)
    .from(orders)
    .inner_join(customers)
      .on(orders.customer_id == customers.customer_id)
    .inner_join(payments)
      .on(orders.order_id == payments.order_id)
    .select(orders.order_id, customers.name, payments.amount)
    .order_by(payments.amount, sqlgen::Descending)
    .execute();

  return results;
}

}  // namespace join_orders_customers_payments
