#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace cascade_delete_demo {

struct Parent {
  sqlgen::PrimaryKey<int> parent_id;
  std::string name;
};

struct Child {
  sqlgen::PrimaryKey<int> child_id;
  sqlgen::ForeignKey<int, Parent, "parent_id"> parent_id;
  std::string note;
};

/**
 * Demonstrates cascade delete behavior in SQLite using foreign key constraints.
 * Returns: bool - true if cascade delete worked correctly, false otherwise.
 */
bool cascade_delete_demo() {
  // Connect to SQLite database
  auto db = sqlgen::sqlite::open("test_db.sqlite");

  // Enable foreign key constraints in SQLite (required for CASCADE to work)
  db.execute("PRAGMA foreign_keys = ON");

  // Drop existing tables if they exist (for clean demo)
  db.execute("DROP TABLE IF EXISTS Child");
  db.execute("DROP TABLE IF EXISTS Parent");

  // Create Parent and Child tables with proper constraints
  db.create_table<Parent>();
  db.create_table<Child>();

  // Insert parent record
  Parent parent;
  parent.parent_id = 1;
  parent.name = "Parent 1";
  db.insert(parent);

  // Insert child records with the same parent_id
  Child child1;
  child1.child_id = 1;
  child1.parent_id = 1;
  child1.note = "Child 1";
  db.insert(child1);

  Child child2;
  child2.child_id = 2;
  child2.parent_id = 1;
  child2.note = "Child 2";
  db.insert(child2);

  // Verify children exist before deletion
  auto children_before = db.select<Child>().where("parent_id = 1").execute();
  if (children_before.size() != 2) {
    return false;  // Children were not inserted properly
  }

  // Delete parent record (should cascade to children)
  db.remove<Parent>().where("parent_id = 1").execute();

  // Verify that child records were automatically deleted due to CASCADE
  auto children_after = db.select<Child>().where("parent_id = 1").execute();

  // Return true if no children remain (cascade delete successful)
  return children_after.empty();
}

}  // namespace cascade_delete_demo
