```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace update_set_operations {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
  std::string status;
};

/**
 * description: update_set_operations.
 * This function demonstrates how to use set operations in update statements using sqlgen write API.
 * It returns true if the update operations are successful, and false otherwise.
 * Returns: bool.
 */
bool update_set_operations() {
  try {
    // Connect to SQLite database
    auto db = sqlgen::sqlite::open("test_db.sqlite");

    // Create Account table
    db.create_table<Account>();

    // Insert test data
    Account acc1{1, 1000.0, "active"};
    Account acc2{2, 2000.0, "active"};
    Account acc3{3, 1500.0, "inactive"};

    db.insert(acc1);
    db.insert(acc2);
    db.insert(acc3);

    // Update using set operations
    // Update account 1: set balance to 1500.0
    db.update<Account>()
      .set(&Account::balance, 1500.0)
      .where(&Account::account_id == 1)
      .execute();

    // Update account 2: set status to "inactive"
    db.update<Account>()
      .set(&Account::status, "inactive")
      .where(&Account::account_id == 2)
      .execute();

    // Update account 3: set both balance and status
    db.update<Account>()
      .set(&Account::balance, 2500.0)
      .set(&Account::status, "active")
      .where(&Account::account_id == 3)
      .execute();

    // Verify changes persisted
    auto accounts = db.select<Account>().execute();

    // Check if we have 3 accounts
    if (accounts.size() != 3) {
      return false;
    }

    // Verify account 1: balance should be 1500.0, status should be "active"
    auto acc1_result = db.select<Account>()
      .where(&Account::account_id == 1)
      .execute();
    if (acc1_result.empty() || acc1_result[0].balance != 1500.0 || acc1_result[0].status != "active") {
      return false;
    }

    // Verify account 2: balance should be 2000.0, status should be "inactive"
    auto acc2_result = db.select<Account>()
      .where(&Account::account_id == 2)
      .execute();
    if (acc2_result.empty() || acc2_result[0].balance != 2000.0 || acc2_result[0].status != "inactive") {
      return false;
    }

    // Verify account 3: balance should be 2500.0, status should be "active"
    auto acc3_result = db.select<Account>()
      .where(&Account::account_id == 3)
      .execute();
    if (acc3_result.empty() || acc3_result[0].balance != 2500.0 || acc3_result[0].status != "active") {
      return false;
    }

    return true;

  } catch (...) {
    return false;
  }
}

}  // namespace update_set_operations
```

