#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace select_from_read_to_vector {

struct Book {
  sqlgen::PrimaryKey<int> book_id;
  std::string title;
  int pages;
};

/**
 * description: select_from_read_to_vector.
 * This function demonstrates how to read data from a table using sqlgen read API and store it in a vector.
 * It returns a vector of Book structs, where each struct contains the book_id, title, and pages.
 * Returns: std::vector<Book>, ordered by pages in descending order.
 */
std::vector<Book> select_from_read_to_vector() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Create sample book data
  const auto books = std::vector<Book>({
      Book{.book_id = 1, .title = "The Great Gatsby", .pages = 180},
      Book{.book_id = 2, .title = "To Kill a Mockingbird", .pages = 281},
      Book{.book_id = 3, .title = "1984", .pages = 328},
      Book{.book_id = 4, .title = "Pride and Prejudice", .pages = 432},
      Book{.book_id = 5, .title = "The Catcher in the Rye", .pages = 234}
  });

  // Connect to SQLite, write data, and read it back ordered by pages descending
  return sqlite::connect()
      .and_then(write(std::ref(books)))
      .and_then(select_from<Book>() | order_by("pages"_c.desc()) |
                to<std::vector<Book>>)
      .value();
}

}  // namespace select_from_read_to_vector
```

