```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace analyze_department_employees {

struct Department {
  sqlgen::PrimaryKey<int> department_id;
  std::string department_name;
  std::string location;
};

struct Employee {
  sqlgen::PrimaryKey<int> employee_id;
  int department_id;
  std::string first_name;
  std::string last_name;
  double salary;
};

struct JoinResult {
  std::optional<std::string> department_name;
  std::optional<std::string> first_name;
  std::optional<std::string> last_name;
  std::optional<double> salary;
};

struct JoinAnalysis {
  std::vector<JoinResult> inner_join_results;
  std::vector<JoinResult> left_join_results;
  std::vector<JoinResult> right_join_results;
  std::vector<JoinResult> full_join_results;
};

/**
 * analyze_department_employees
 * Provides data-join analysis between Department and Employee input collections by
 * creating temporary SQL tables, inserting the provided rows, and executing a
 * variety of join queries to produce join-output samples.
 * Returns: JoinAnalysis.
 */
JoinAnalysis analyze_department_employees_impl(const std::vector<Department>& depts, const std::vector<Employee>& emps) {
  JoinAnalysis analysis;

  // Create SQLite connection
  auto db = sqlgen::sqlite::connect("test_db.sqlite");

  // Create Department table
  db.execute(R"(
    CREATE TABLE IF NOT EXISTS Department (
      department_id INTEGER PRIMARY KEY,
      department_name VARCHAR(100) NOT NULL,
      location VARCHAR(100)
    )
  )");

  // Create Employee table
  db.execute(R"(
    CREATE TABLE IF NOT EXISTS Employee (
      employee_id INTEGER PRIMARY KEY,
      department_id INTEGER,
      first_name VARCHAR(50) NOT NULL,
      last_name VARCHAR(50) NOT NULL,
      salary REAL NOT NULL,
      FOREIGN KEY (department_id) REFERENCES Department(department_id)
    )
  )");

  // Clear existing data
  db.execute("DELETE FROM Employee");
  db.execute("DELETE FROM Department");

  // Insert departments
  for (const auto& dept : depts) {
    auto stmt = db.prepare(
      "INSERT INTO Department (department_id, department_name, location) VALUES (?, ?, ?)"
    );
    stmt.bind(1, dept.department_id.value);
    stmt.bind(2, dept.department_name);
    stmt.bind(3, dept.location);
    stmt.execute();
  }

  // Insert employees
  for (const auto& emp : emps) {
    auto stmt = db.prepare(
      "INSERT INTO Employee (employee_id, department_id, first_name, last_name, salary) VALUES (?, ?, ?, ?, ?)"
    );
    stmt.bind(1, emp.employee_id.value);
    stmt.bind(2, emp.department_id);
    stmt.bind(3, emp.first_name);
    stmt.bind(4, emp.last_name);
    stmt.bind(5, emp.salary);
    stmt.execute();
  }

  // 1. INNER JOIN - Get employees with assigned departments
  {
    auto stmt = db.prepare(R"(
      SELECT d.department_name, e.first_name, e.last_name, e.salary
      FROM Department d
      INNER JOIN Employee e ON d.department_id = e.department_id
    )");

    while (stmt.step()) {
      JoinResult result;
      result.department_name = stmt.column_text(0);
      result.first_name = stmt.column_text(1);
      result.last_name = stmt.column_text(2);
      result.salary = stmt.column_double(3);
      analysis.inner_join_results.push_back(result);
    }
  }

  // 2. LEFT JOIN - Include all employees (even without departments)
  {
    auto stmt = db.prepare(R"(
      SELECT d.department_name, e.first_name, e.last_name, e.salary
      FROM Employee e
      LEFT JOIN Department d ON e.department_id = d.department_id
    )");

    while (stmt.step()) {
      JoinResult result;
      if (!stmt.column_is_null(0)) {
        result.department_name = stmt.column_text(0);
      }
      result.first_name = stmt.column_text(1);
      result.last_name = stmt.column_text(2);
      result.salary = stmt.column_double(3);
      analysis.left_join_results.push_back(result);
    }
  }

  // 3. RIGHT JOIN - Include all departments (even without employees)
  // SQLite doesn't support RIGHT JOIN directly, so we use LEFT JOIN with reversed tables
  {
    auto stmt = db.prepare(R"(
      SELECT d.department_name, e.first_name, e.last_name, e.salary
      FROM Department d
      LEFT JOIN Employee e ON d.department_id = e.department_id
    )");

    while (stmt.step()) {
      JoinResult result;
      result.department_name = stmt.column_text(0);
      if (!stmt.column_is_null(1)) {
        result.first_name = stmt.column_text(1);
      }
      if (!stmt.column_is_null(2)) {
        result.last_name = stmt.column_text(2);
      }
      if (!stmt.column_is_null(3)) {
        result.salary = stmt.column_double(3);
      }
      analysis.right_join_results.push_back(result);
    }
  }

  // 4. FULL JOIN - Include all employees and departments
  // SQLite doesn't support FULL JOIN, so we use UNION of LEFT and RIGHT joins
  {
    auto stmt = db.prepare(R"(
      SELECT d.department_name, e.first_name, e.last_name, e.salary
      FROM Employee e
      LEFT JOIN Department d ON e.department_id = d.department_id
      UNION
      SELECT d.department_name, e.first_name, e.last_name, e.salary
      FROM Department d
      LEFT JOIN Employee e ON d.department_id = e.department_id
    )");

    while (stmt.step()) {
      JoinResult result;
      if (!stmt.column_is_null(0)) {
        result.department_name = stmt.column_text(0);
      }
      if (!stmt.column_is_null(1)) {
        result.first_name = stmt.column_text(1);
      }
      if (!stmt.column_is_null(2)) {
        result.last_name = stmt.column_text(2);
      }
      if (!stmt.column_is_null(3)) {
        result.salary = stmt.column_double(3);
      }
      analysis.full_join_results.push_back(result);
    }
  }

  return analysis;
}

}  // namespace analyze_department_employees
```

