```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace weekday_sales_analysis {

struct Sales {
  sqlgen::PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> sale_time;
};

struct WeekdayStats {
  int weekday;
  int total_quantity;
};

/**
 * Description: This function analyzes sales data to calculate total quantity sold for each weekday.
 * Returns: std::vector<WeekdayStats>.
 */
std::vector<WeekdayStats> weekday_sales_analysis() {
  // Connect to the SQLite database
  sqlgen::sqlite::Database db("test_db.sqlite");

  // Define the Sales table
  auto sales_table = db.table<Sales>("Sales");

  // Query to extract weekday and aggregate totals
  // In SQLite, strftime('%w', datetime) returns day of week (0-6, Sunday is 0)
  auto results = db.query<WeekdayStats>(
    "SELECT CAST(strftime('%w', sale_time) AS INTEGER) as weekday, "
    "SUM(quantity) as total_quantity "
    "FROM Sales "
    "GROUP BY weekday "
    "ORDER BY weekday"
  );

  return results;
}

}  // namespace weekday_sales_analysis
```

